/**
 * Client-side helpers for prescription PDF downloads.
 *
 * The filename is generated by the backend (`prescriptionFileName.ts`), the
 * single naming authority. The web client never builds or edits a name; it
 * reads the server-provided `Content-Disposition` value and refuses to save
 * anything that does not match the documented format.
 */

export const PRESCRIPTION_FILE_NAME_PATTERN =
  /^(?:[A-Z0-9-]+_[A-Za-z0-9][A-Za-z0-9-]*_RX-\d{8}-[A-Z0-9]+(?:_replaces-[A-Z0-9]+)?(?:_SUPERSEDED)?|RX-\d{8}-[A-Z0-9]+)\.pdf$/;

/** Extract the filename from a `Content-Disposition` response header. */
export function prescriptionFileNameFromDisposition(disposition: string): string | null {
  const match = /filename="?([^";]+)"?/i.exec(disposition || '');
  const fileName = match?.[1]?.trim();
  return fileName ? fileName : null;
}

/** True when the filename follows the shared prescription PDF contract. */
export function isPrescriptionFileName(fileName: string): boolean {
  return PRESCRIPTION_FILE_NAME_PATTERN.test(String(fileName ?? ''));
}
